const db=new DatabaseSync('/bench/home/work/.codegraph/codegraph.db',{readOnly:true});
const rows=db.prepare(\`
select n.name, n.qualified_name, n.file_path, n.start_line, n.kind,
  count(*) as sites, count(distinct e.source) as callers
from edges e join nodes n on n.id=e.target
where e.kind='calls' and n.file_path like 'internal/%' and n.kind in ('function','method')
group by n.id order by callers desc limit 25\`).all();
for(const r of rows) console.log(r.callers, r.sites, r.kind, r.qualified_name, r.file_path+':'+r.start_line);
" 2>&1 | grep -v Warning

